-- Step 1: shared authentication model for the Online Discussion Tool.
-- MySQL 8.0+ migration. Run with: mysql -u root -p < 001_login.sql
-- Store a password hash generated by the server, never a plaintext password.

CREATE DATABASE IF NOT EXISTS discussion_tool
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE discussion_tool;

CREATE TABLE IF NOT EXISTS user_account (
    user_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(60) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role ENUM('INSTRUCTOR', 'STUDENT') NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    password_changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS student_record (
    student_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT NOT NULL UNIQUE,
    student_number VARCHAR(50) NOT NULL UNIQUE,
    firstname VARCHAR(100) NOT NULL,
    lastname VARCHAR(100) NOT NULL,
    CONSTRAINT fk_student_user
        FOREIGN KEY (user_id) REFERENCES user_account (user_id)
        ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE INDEX idx_user_account_username ON user_account (username);
CREATE INDEX idx_student_record_user_id ON student_record (user_id);

CREATE TABLE IF NOT EXISTS user_session (
    session_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT NOT NULL,
    session_token_hash VARCHAR(255) NOT NULL UNIQUE,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at DATETIME NOT NULL,
    revoked_at DATETIME,
    CONSTRAINT fk_session_user
        FOREIGN KEY (user_id) REFERENCES user_account (user_id)
        ON DELETE CASCADE
 ) ENGINE=InnoDB;

CREATE INDEX idx_user_session_user_id ON user_session (user_id);
CREATE INDEX idx_user_session_active ON user_session (session_token_hash, expires_at, revoked_at);

-- Password changes must be performed by the application inside a transaction:
--
-- Login: look up the account by username and compare the submitted password
-- with password_hash using the server's password-hashing library, then insert:
--
-- INSERT INTO user_session (user_id, session_token_hash, expires_at)
-- VALUES (:user_id, :session_token_hash, :expires_at);
--
-- Logout:
--
-- UPDATE user_session
-- SET revoked_at = CURRENT_TIMESTAMP
-- WHERE session_token_hash = :session_token_hash
--   AND revoked_at IS NULL;
--
-- Change password:
-- UPDATE user_account
-- SET password_hash = :new_password_hash,
--     password_changed_at = CURRENT_TIMESTAMP
-- WHERE user_id = :user_id;